import { readFileSync, readdirSync } from 'node:fs';
import { resolve, relative, sep } from 'node:path';
import { pathToFileURL } from 'node:url';
import { parse } from 'parse5';

/** Check the published output, including links generated by the theme and MDX. */
export function checkLinks(directory, origin = 'https://cpo3-org.github.io') {
  const root = resolve(directory);
  const siteOrigin = new URL(origin).origin;
  const files = new Set(readdirSync(root, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) => resolve(entry.parentPath, entry.name)));
  const pages = new Map();
  for (const file of files) {
    if (!file.endsWith('.html')) continue;
    const ids = new Set();
    const links = [];
    function visit(node, versionSelect = false) {
      const attrs = Object.fromEntries((node.attrs || []).map(({ name, value }) => [name, value]));
      versionSelect ||= (attrs.class || '').split(/\s+/).includes('version-select');
      if (attrs.id) ids.add(attrs.id);
      if (node.tagName === 'a' && attrs.name) ids.add(attrs.name);
      for (const attribute of ['href', 'src']) {
        if (attrs[attribute]) links.push({ value: attrs[attribute], line: node.sourceCodeLocation?.startLine });
      }
      if (versionSelect && node.tagName === 'option' && attrs.value) {
        links.push({ value: attrs.value, line: node.sourceCodeLocation?.startLine });
      }
      for (const child of node.childNodes || []) visit(child, versionSelect);
    }
    visit(parse(readFileSync(file, 'utf8'), { sourceCodeLocationInfo: true }));
    pages.set(file, { ids, links });
  }
  if (!pages.size) throw new Error(`No HTML pages found in ${directory}; run npm run build first.`);

  const errors = [];
  let checked = 0;
  for (const [file, page] of pages) {
    const name = relative(root, file).split(sep).join('/');
    const pageUrl = new URL(`/${name.replace(/(^|\/)index\.html$/, '$1')}`, siteOrigin);
    for (const { value, line } of page.links) {
      const fail = (reason) => errors.push(`${name}:${line ?? '?'}: ${value} — ${reason}`);
      let url;
      try {
        url = new URL(value, pageUrl);
      } catch {
        fail('invalid URL');
        continue;
      }
      if (url.origin !== siteOrigin) continue;
      checked++;
      let pathname, fragment;
      try {
        pathname = decodeURIComponent(url.pathname);
        // Text fragments are browser directives, not element IDs.
        fragment = decodeURIComponent(url.hash.slice(1).split(':~:')[0]);
      } catch {
        fail('invalid percent encoding');
        continue;
      }
      const path = resolve(root, `.${pathname}`);
      const target = [path, resolve(path, 'index.html'), `${path}.html`]
        .find((candidate) => files.has(candidate));
      if (!target) {
        fail('target does not exist');
      } else if (fragment && fragment.toLowerCase() !== 'top'
        && pages.has(target) && !pages.get(target).ids.has(fragment)) {
        fail(`anchor #${fragment} does not exist in ${relative(root, target)}`);
      }
    }
  }
  return { pages: pages.size, checked, errors };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    const { pages, checked, errors } = checkLinks(process.argv[2] || 'dist');
    for (const error of errors) console.error(error);
    console.log(`Checked ${checked} internal references in ${pages} HTML pages: ${errors.length} errors.`);
    if (errors.length) process.exitCode = 1;
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}
